func TestCrossLinkCallSitePassesTheRealPageLive(t *testing.T) {
    db, mock, _ := sqlmock.New(); mock.MatchExpectationsInOrder(false)
    // the tool page is SERVED, and the opt-in is OFF — the discriminating setup
    mock.ExpectQuery(`SELECT COALESCE\(build_status, ''\) FROM pages WHERE id = \$1`).
        WithArgs(toolPageID).WillReturnRows(...AddRow("deployed"))
    // the gate-item lookup is deliberately UNREGISTERED: correct code never issues it
    mock.ExpectQuery(`SELECT name, id FROM pages`).WillReturnRows(...AddRow("services", relatedPageID))
    mock.ExpectQuery(`SELECT COUNT(*)`).WillReturnRows(...AddRow(0, 0.0))  // two-strike: suppresses nothing
    mock.ExpectBegin(); mock.ExpectExec(`INSERT INTO site_work_items`).WillReturnResult(...); mock.ExpectCommit()
    created := emitToolCrossLinkItems(ctx, params, zap.NewNop(), toolCrossLinkRequest{
        ..., pageBuildIsEnqueuedByThisWorkflow: false})  // OPT-IN OFF
    if created != 1 { t.Fatalf("...the call site is not passing the real pageLive...") }
}
